do $$
declare
  v_course_id uuid := 'e0c4e391-99a7-4c64-8258-3077b62b17de';
  v_level uuid;
  -- modules.order_number is unique per COURSE, not per level (a course's
  -- modules are numbered continuously across all its levels) -- so this
  -- can't just start at 1 for a level beyond the first. Computed here
  -- instead of hardcoded so this script works correctly regardless of how
  -- many modules the course already has.
  v_module_offset int;
  v_m1 uuid;
  v_m2 uuid;
begin
  -- Appending to a level that already exists. Looked up rather than
  -- inserted, so this adds to the learner's current Level 1 instead of
  -- creating a duplicate one, and no existing module is re-parented.
  select id into v_level from public.levels
    where course_id = v_course_id and order_number = 1;

  if v_level is null then
    raise exception 'Level % not found for course % -- refusing to guess', 1, v_course_id;
  end if;

  -- The new modules must sit INSIDE this level, not at the end of the
  -- course. getOrderedLessons() builds the learner's lesson sequence from
  -- modules.order_number alone and ignores level, so a module appended at
  -- the course's max order would put beginner content after the final
  -- level's material. Insert straight after this level's last module and
  -- shift everything below it down instead.
  select coalesce(max(order_number), 0) into v_module_offset
    from public.modules where level_id = v_level;

  -- Two-phase shift: (course_id, order_number) is unique, and a single
  -- "+ N" update can trip that constraint mid-statement, so park the rows
  -- out of range first and bring them back afterwards.
  update public.modules set order_number = order_number + 1000
   where course_id = v_course_id and order_number > v_module_offset;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'Planning the Work Before You Open the Tool', 'The existing lessons teach Trello, Notion and Asana. This one teaches the part that decides whether any of them help: working out what the tasks actually are.', v_module_offset + 1)
  returning id into v_m1;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m1, 'What a Project Plan Actually Contains', 'ProjectManager on planning a project from scratch — scope, deliverables, schedule and the order things have to happen in. Under 6 minutes.', 'https://www.youtube.com/watch?v=ZWmXi3TW1yA', 1,
      array['State a project''s goal and scope in a sentence anyone can check', 'Identify deliverables, deadlines and who is responsible for each', 'Spot dependencies — the tasks that cannot start until another finishes'],
      'A board full of cards is not a plan. It is a list. The difference is that a plan says what finished looks like, when, and in what order — and a list does not.

FOUR THINGS EVERY PLAN NEEDS, however small the project:

THE GOAL, in one sentence, written so someone else could tell you whether it has been achieved. "Improve the website" fails that test. "Launch a 5-page site with working contact form by 30 November" passes it.

SCOPE — what is included and, more importantly, WHAT IS NOT. Write the exclusions down. Almost every project that runs over does so because things quietly got added, one small favour at a time. The written line is what lets you say "that is a second phase" without an argument.

DELIVERABLES — the actual things that will exist at the end. Not activities. "Design the logo" is an activity; "final logo files in PNG and SVG" is a deliverable. You can point at a deliverable and agree it is done.

DEPENDENCIES — which tasks cannot start until another finishes. You cannot print the banners before the design is approved. Dependencies, not effort, are what make projects late: a two-hour task that blocks four other people costs far more than two hours.

AND ONE OWNER PER TASK. Not a team — a person. "The team will handle it" reliably means nobody did. Two names on a task is the same as none.

Write the plan before you build the board. Then the board is a place to track work you have already thought about, rather than a place to think.',
      'Take something real you need to do in the next month. Write four lines: the goal in one checkable sentence, three things that are explicitly NOT included, the deliverables that will exist at the end, and one person''s name against each. Then list every task that cannot start until another finishes. That last list is your risk list — it is where the delay will come from.',
      '[{"question":"Why is writing down what is NOT in scope so important?","options":["It is what lets you push back when work quietly gets added later","Clients are legally required to sign it","It makes the project finish faster","Project tools refuse to create a board without it"],"correct_index":0},{"question":"What usually makes a project late?","options":["Dependencies — small tasks that block several other people","The total number of tasks on the board","How many tools the team uses","The length of the status meeting"],"correct_index":0}]'::jsonb),
    (v_m1, 'Breaking a Project into Tasks You Can Actually Assign', 'A clear walkthrough of the work breakdown structure — splitting a big deliverable into pieces small enough to put on a card and finish. Under 6 minutes.', 'https://www.youtube.com/watch?v=BVcd9uy9kuQ', 2,
      array['Split a large deliverable into tasks a person can finish in a day or two', 'Write a task so the person doing it knows when it is done', 'Recognise a task that is really a project in disguise'],
      'This is the single most useful skill in the whole course, and no tool does it for you. Trello will happily hold a card saying "build website" for six months.

THE TEST FOR A GOOD TASK: one person, one clear finish, a day or two of work. If any of those three fails, break it down further.

- More than one person? It is two tasks.
- Cannot say precisely when it is done? Rewrite it until you can.
- More than about two days? It will sit at "in progress" for weeks and nobody, including the person doing it, will know how far along it is.

HOW TO BREAK IT DOWN: start from the deliverable and split it into the pieces that make it up, then split those, and stop when each piece passes the test. "Website" becomes pages, forms, hosting and content; "content" becomes copy for each page; "copy" becomes one task per page. What you end up with is a board that reflects reality.

WRITE THE DONE CONDITION INTO THE CARD. Not "homepage copy" but "homepage copy written, under 400 words, approved by James". The card should answer, without a conversation, the question the person will actually have: how do I know I have finished?

A TASK THAT KEEPS COMING BACK is a sign it was never broken down. "Fix the bugs" is not a task; it is a category. Every bug is its own card.

AND ESTIMATE AFTER BREAKING DOWN, never before. Nobody can estimate "build website" honestly. Almost anyone can estimate "write the about page". Add the small ones up and you have an estimate you can defend — usually a bigger one than your first guess, which is the point.',
      'Take the biggest single item on any list you keep and break it down until every piece passes the test: one person, one clear finish, a day or two. Count how many cards you end up with. Then write the done condition into each one as a sentence. If you cannot write that sentence for a card, it still is not a task.',
      '[{"question":"Which of these is a properly broken-down task?","options":["Write the about page copy, under 400 words, approved by James","Fix the bugs","Improve the website","Handle marketing"],"correct_index":0},{"question":"When should you estimate how long work will take?","options":["After breaking it down, by adding up the small pieces","Before breaking it down, so the estimate stays optimistic","Only once the work has started","Estimates are not useful on small projects"],"correct_index":0}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'Keeping the Project Moving', 'How work should flow through a board, and how to show whoever is paying that it is actually progressing.', v_module_offset + 2)
  returning id into v_m2;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m2, 'How Work Should Flow Through a Board', 'Atlassian — the company behind Trello and Jira — on what agile working actually means, beneath the jargon. About 5 minutes.', 'https://www.youtube.com/watch?v=4Ugsu2n2cLE', 1,
      array['Explain what the columns on a board represent', 'Limit work in progress and say why finishing beats starting', 'Work in short cycles instead of one long push to a deadline'],
      'Agile has been buried under jargon and certifications, but the core of it is small and genuinely useful: work in short cycles, show real progress often, and change the plan when you learn something.

A BOARD''S COLUMNS ARE A PROCESS, not decoration. To Do, In Progress, Done is the minimum. Add a column only when it represents a real handover — a Review column earns its place if someone genuinely checks the work; it is clutter if nobody does.

THE RULE THAT CHANGES EVERYTHING: LIMIT WORK IN PROGRESS. Decide the maximum number of cards allowed in the In Progress column at once — for one person, two or three; for a small team, roughly one or two each. When you hit the limit, you may not start anything new. You must finish something first.

This feels wrong and is almost always right. Ten things at 80% deliver nothing. Three things finished deliver three things. Switching between tasks also costs real time — every switch means re-reading where you were.

A BOARD WITH TWENTY CARDS IN PROGRESS IS LYING. Nothing is in progress; twenty things are stalled. That is the most common failure in every tool this course covers, and it is a discipline problem, not a software problem.

SHORT CYCLES BEAT ONE BIG PUSH. Pick a week''s worth of work, finish it, look at what you learned, then pick the next. Long plans built in month one are always wrong by month three, because you know more by then. That is not bad planning — it is what planning is for.

MOVE CARDS THE SAME DAY. A board updated weekly is a report. A board updated as things happen is a tool.',
      'Open whichever board you use and count the cards sitting in In Progress. Set a limit — three if you are working alone — and move everything above it back to To Do, in priority order. Work only from the top for a week. Notice both how uncomfortable it is and how much more actually reaches Done.',
      '[{"question":"Why limit the number of cards in progress at once?","options":["Finishing a few things delivers value; many half-done things deliver none","Boards slow down with too many cards","Most tools charge per active card","It makes the board look tidier to clients"],"correct_index":0},{"question":"When should a card be moved to a new column?","options":["The same day the work actually changes state","At the weekly meeting, all at once","When the client asks for an update","At the end of the project"],"correct_index":0}]'::jsonb),
    (v_m2, 'Tracking Progress and Reporting It', 'ProjectManager on what belongs in a project status report — what to include, what to leave out, and how to raise a problem early. Under 7 minutes.', 'https://www.youtube.com/watch?v=5mvXSAJgqec', 2,
      array['Report status in a form a busy person can read in a minute', 'Raise a delay or blocker early rather than hoping it resolves', 'Run a short check-in that surfaces problems instead of reciting tasks'],
      'Whoever is paying for the project — a client, a manager, a committee — has one question: are we going to get what we agreed, on time? Everything in a status report exists to answer that.

WHAT A USABLE STATUS REPORT CONTAINS:
- One line at the top: on track, at risk, or off track. Say it plainly.
- What was completed since last time
- What is next
- BLOCKERS, and what you need from them to clear each one
- Any change to the deadline or the budget, stated directly

That is a page at most. A twelve-page report gets skimmed, and the one paragraph that mattered gets missed.

RAISE PROBLEMS EARLY. This is the whole job. A delay reported three weeks ahead is a scheduling conversation; the same delay reported the day before the deadline is a crisis and a lost client. Nobody has ever been fired for flagging a risk early. Plenty have been for hiding one that later became obvious.

DO NOT LET A BLOCKER SIT SILENTLY. If a task is stuck waiting for someone else, say so, name what you need, and give a date. A blocker nobody knows about is not being solved by anyone.

THE CHECK-IN THAT WORKS is short and asks three questions per person: what did you finish, what is next, what is in your way. Ten minutes, standing up, not a meeting where everyone narrates their week. The third question is the only one that matters — the other two are warm-up.

AND KEEP THE BOARD AS THE SOURCE OF TRUTH. If the report and the board disagree, people stop trusting both, and then everyone goes back to asking each other by WhatsApp — which is exactly the state the tool was meant to replace.',
      'Write a one-page status update for something you are working on, using the five headings above, and lead with on track / at risk / off track. Force yourself to name at least one blocker and exactly what you need to clear it, from whom, by when. Then send it. The discomfort of naming a blocker in writing is the skill this lesson is teaching.',
      '[{"question":"When should a likely delay be reported?","options":["As soon as you can see it coming, while options still exist","Once it is certain and unavoidable","At the end of the project, in the final report","Only if the client asks directly"],"correct_index":0},{"question":"Which question makes a daily check-in worth holding?","options":["What is in your way?","What did you work on yesterday?","How many hours did you log?","Which tool are you using?"],"correct_index":0}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

